package com.tradingcards.uploader  import com.tradingcards.uploader.data.GalleryRepository import com.tradingcards.uploader.model.GalleryCategory import com.tradingcards.uploader.model.GalleryImage import com.tradingcards.uploader.model.GalleryImagesResponse import com.tradingcards.uploader.ui.GalleryUiState import kotlinx.coroutines.CancellationException  internal enum class GalleryRefreshReason {     Initial,     Category,     Manual,     Action,     Poll, }  internal data class LoadedGallery(     val selectedCategory: GalleryCategory,     val items: List<GalleryImage>,     val nextCursor: String?, )  internal data class GallerySnapshot(     val items: List<GalleryImage>,     val nextCursor: String?, )  /**  * Loads gallery pages via the scanner's cursor pagination. Fetches one page  * by default; when [minItems] is set (poll/action refreshes), keeps following  * `nextCursor` so an already-scrolled gallery keeps its loaded depth.  */ internal suspend fun loadGallery(     token: String,     category: GalleryCategory,     repository: GalleryRepository,     minItems: Int = 0, ): LoadedGallery {     val items = mutableListOf<GalleryImage>()     var cursor: String? = null     do {         val page = repository.list(token, category, cursor)         items += page.items         cursor = page.nextCursor     } while (cursor != null && items.size < minItems)     return LoadedGallery(         selectedCategory = category,         items = items.distinctBy { it.name },         nextCursor = cursor,     ) }  internal fun galleryStateForRefreshStart(     state: GalleryUiState,     category: GalleryCategory,     reason: GalleryRefreshReason,     cachedSnapshot: GallerySnapshot? = null, ): GalleryUiState =     when (reason) {         GalleryRefreshReason.Poll -> state         GalleryRefreshReason.Action ->             state.copy(                 loading = true,                 loadingMore = false,                 errorText = null,             )         GalleryRefreshReason.Initial,         GalleryRefreshReason.Manual,         ->             state.copy(                 category = category,                 loading = true,                 loadingMore = false,                 selectedNames = emptySet(),                 nextCursor = null,                 errorText = null,             )         GalleryRefreshReason.Category ->             state.copy(                 category = category,                 items = cachedSnapshot?.items.orEmpty(),                 nextCursor = cachedSnapshot?.nextCursor,                 loading = true,                 loadingMore = false,                 selectedNames = emptySet(),                 errorText = null,             )     }  internal fun galleryStateForRefreshSuccess(     state: GalleryUiState,     token: String,     loaded: LoadedGallery,     reason: GalleryRefreshReason, ): GalleryUiState {     val loadedNames = loaded.items.map { it.name }.toSet()     val selectedNames =         if (reason == GalleryRefreshReason.Poll) {             state.selectedNames.intersect(loadedNames)         } else {             emptySet()         }     return state.copy(         category = loaded.selectedCategory,         items = loaded.items,         nextCursor = loaded.nextCursor,         selectedNames = selectedNames,         loading = false,         loadingMore = false,         errorText = null,         accessToken = token,     ) }  internal fun galleryStateForLoadMoreStart(state: GalleryUiState): GalleryUiState = state.copy(loadingMore = true)  internal fun galleryStateForLoadMoreSuccess(     state: GalleryUiState,     page: GalleryImagesResponse, ): GalleryUiState =     state.copy(         items = (state.items + page.items).distinctBy { it.name },         nextCursor = page.nextCursor,         loadingMore = false,     )  internal fun galleryStateForLoadMoreFailure(     state: GalleryUiState,     message: String?, ): GalleryUiState =     state.copy(         loadingMore = false,         errorText = "Couldn't load more images: ${message ?: "unknown error"}",     )  internal fun galleryStateForRefreshFailure(     state: GalleryUiState,     reason: GalleryRefreshReason,     message: String?, ): GalleryUiState =     when (reason) {         GalleryRefreshReason.Poll -> state         GalleryRefreshReason.Action ->             state.copy(                 loading = false,                 errorText = "Action failed: ${message ?: "unknown error"}",             )         GalleryRefreshReason.Initial,         GalleryRefreshReason.Category,         GalleryRefreshReason.Manual,         ->             state.copy(                 loading = false,                 errorText = "Couldn't load images: ${message ?: "unknown error"}",             )     }  internal fun throwIfCancellation(error: Throwable) {     if (error is CancellationException) {         throw error     } }